import{_ as a,o as l,c as e,a2 as s}from"./chunks/framework.Dnfa3P0E.js";const k=JSON.parse('{"title":"交付契约与执行台账规则","description":"","frontmatter":{},"headers":[],"relativePath":"mango-pmo/rules/01-delivery-contract.md","filePath":"mango-pmo/rules/01-delivery-contract.md"}'),o={name:"mango-pmo/rules/01-delivery-contract.md"};function t(d,i,n,h,r,c){return l(),e("div",null,[...i[0]||(i[0]=[s(`<h1 id="交付契约与执行台账规则" tabindex="-1">交付契约与执行台账规则 <a class="header-anchor" href="#交付契约与执行台账规则" aria-label="Permalink to &quot;交付契约与执行台账规则&quot;">​</a></h1><h2 id="_1-适用范围" tabindex="-1">1. 适用范围 <a class="header-anchor" href="#_1-适用范围" aria-label="Permalink to &quot;1. 适用范围&quot;">​</a></h2><p>本文件只定义交付契约、轻量设计说明和执行台账在适用时如何编写、检查和复用。交付模式、工作区策略和 M01-M16 启用逻辑只在 <code>mango-pmo/rules/11-delivery-assurance.md</code> 维护，本文件不复制判定正文。</p><ul><li><code>SIMPLE</code> 直接实现，不创建本文资产。</li><li><code>STANDARD</code> 使用 <code>mango-pmo/templates/standard-delivery-record.md</code> 单文件，不再额外创建本文台账。</li><li><code>FULL</code> 只有在范围较大、需要逐项追踪多类交付物时，才使用交付契约或执行台账；产品阶段文档继续使用 BRD/SRS/TDD/Plan，治理和发布使用各自专用记录。</li><li>发布由独立发布流程处理，本文不提供发布授权或恢复门禁。</li></ul><h2 id="_2-目标" tabindex="-1">2. 目标 <a class="header-anchor" href="#_2-目标" aria-label="Permalink to &quot;2. 目标&quot;">​</a></h2><p>防止复杂任务被压缩成极简主链路、聚合页、演示页、临时实现或不可验收交付，同时避免简单和标准任务承担重复文档成本。</p><h2 id="_3-开工门禁" tabindex="-1">3. 开工门禁 <a class="header-anchor" href="#_3-开工门禁" aria-label="Permalink to &quot;3. 开工门禁&quot;">​</a></h2><p>模式基线判定 FULL 且任务需要交付契约作为追踪载体时，开始对应工作前必须明确：</p><ul><li>目标、范围和不处理范围</li><li>设计输入和交付物</li><li>验收方式和证据</li><li>测试用例登记与自动化判断</li><li>E2E 覆盖判断</li><li>测试结果基线</li><li>业务开发交接输出</li><li>风险与限制</li></ul><h2 id="_4-设计说明门禁" tabindex="-1">4. 设计说明门禁 <a class="header-anchor" href="#_4-设计说明门禁" aria-label="Permalink to &quot;4. 设计说明门禁&quot;">​</a></h2><ul><li>已有适用设计文档时，设计说明必须引用该文档并抽取原子要求。</li><li>FULL 非产品任务没有适用 TDD 时，可以使用轻量设计说明，但必须引用模式基线和事实来源。</li><li>设计说明必须写清模块边界、接口变化、数据变化、菜单、页面、权限和测试范围中的适用项。</li><li>对外能力新增、修改、删除或重构时，必须说明 README、能力文档、设计资产、E2E 和测试结果基线是否需要同步。</li><li>禁止未经用户确认把完整任务缩减为 MVP、第一阶段、纵向切片或演示版本。</li></ul><h2 id="_5-执行台账门禁" tabindex="-1">5. 执行台账门禁 <a class="header-anchor" href="#_5-执行台账门禁" aria-label="Permalink to &quot;5. 执行台账门禁&quot;">​</a></h2><p>FULL 任务需要原子交付追踪时，执行台账从已批准需求、设计和验收标准抽取原子项，不得为了填表额外启用无关能力。</p><p>每项至少记录：</p><ul><li><code>ID</code></li><li><code>来源</code></li><li><code>要求</code></li><li><code>设计决策</code></li><li><code>代码交付物</code></li><li><code>说明或文档</code></li><li><code>验证与证据</code></li><li><code>状态</code></li></ul><p>推荐模板：<code>mango-pmo/templates/delivery-contract.md</code>。</p><h2 id="_6-原子验收项规则" tabindex="-1">6. 原子验收项规则 <a class="header-anchor" href="#_6-原子验收项规则" aria-label="Permalink to &quot;6. 原子验收项规则&quot;">​</a></h2><ul><li>后台、业务、接口、数据、菜单、页面、权限和验收标准中的独立能力必须分别登记。</li><li>禁止把多个能力合并成“管理页”“概览页”“主流程”或“通用能力”一项。</li><li>只有模式基线启用的能力说明和验证措施才要求对应材料；未启用项不得为了表格完整而补建。</li><li>无法落地的项必须标记为 <code>EXCEPTION</code>，并记录批准依据和剩余风险。</li></ul><h2 id="_7-禁止替代" tabindex="-1">7. 禁止替代 <a class="header-anchor" href="#_7-禁止替代" aria-label="Permalink to &quot;7. 禁止替代&quot;">​</a></h2><ul><li>用聚合页替代多个独立管理页面。</li><li>用 MVP、第一阶段或纵向切片替代已确认完整范围。</li><li>用主链路跑通替代完整后台、接口、数据和验收能力。</li><li>用前端临时菜单替代后端入库菜单。</li><li>用 Mock、虚拟或演示数据替代要求的沙箱或真实能力。</li><li>用单元测试、接口 200、页面打开或口头说明替代应有的真实入口证据。</li><li>用“后续优化”或“未来补齐”替代本次明确要求。</li></ul><h2 id="_8-验证门禁" tabindex="-1">8. 验证门禁 <a class="header-anchor" href="#_8-验证门禁" aria-label="Permalink to &quot;8. 验证门禁&quot;">​</a></h2><p>FULL 采用本文资产时，交付前执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mango-pmo/tools/delivery-contract-check.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --design</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">设计说明或设计文档路</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">径</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --ledger</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">执行台账路</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">径</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --mode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify</span></span></code></pre></div><p>验证必须满足：</p><ul><li>设计说明或适用设计文档存在。</li><li>台账存在且必填列完整。</li><li>必需交付项存在。</li><li>状态为 <code>DONE</code> 或 <code>EXCEPTION</code>。</li><li><code>EXCEPTION</code> 有批准证据和剩余风险。</li><li>交付范围内不存在未处理的 <code>TODO</code>、<code>FIXME</code>、Mock、伪代码或延期标记。</li></ul><h2 id="_9-交付报告" tabindex="-1">9. 交付报告 <a class="header-anchor" href="#_9-交付报告" aria-label="Permalink to &quot;9. 交付报告&quot;">​</a></h2><p>采用执行台账时，最终报告台账路径、总项数、<code>DONE</code> 数、<code>EXCEPTION</code> 数、验证证据、未完成项和检查结果。未完成项不为 0 时禁止声明完成。</p>`,27)])])}const u=a(o,[["render",t]]);export{k as __pageData,u as default};
